def Q(prompt, correct, wrongs, steps, concept, skill, hint, diagram="", alt="", pos=None):
    """Four-option MC spec. `wrongs` = [(text, why)] x3. Position is balanced by build()."""
    return {"k": "mc", "prompt": prompt, "correct": correct, "wrongs": wrongs, "steps": steps, "concept": concept,
            "skill": skill, "hint": hint, "diagram": diagram, "alt": alt, "pos": pos}


def LQ(prompt, ans, whys, steps, concept, skill, hint, diagram, alt):
    """MC about lettered parts of a diagram: options are the letters A-D, in order. `whys` = {letter: why} for the wrong letters."""
    letters = "ABCD"
    assert ans in letters and set(whys) == set(letters) - {ans}, (prompt, ans, whys)
    return {"k": "lq", "prompt": prompt, "ans": ans, "whys": whys, "steps": steps, "concept": concept, "skill": skill,
            "hint": hint, "diagram": diagram, "alt": alt, "pos": letters.index(ans)}


def FQ(prompt, options, ans, whys, steps, concept, skill, hint, diagram="", alt=""):
    """MC with options in a fixed order (for example '1 and 2 only'). `ans` is the 0-based index; `whys` = {index: why}."""
    assert len(options) == 4 and set(whys) == set(range(4)) - {ans}, (prompt, ans, whys)
    return {"k": "fq", "prompt": prompt, "options": options, "ans": ans, "whys": whys, "steps": steps, "concept": concept,
            "skill": skill, "hint": hint, "diagram": diagram, "alt": alt, "pos": ans}


def N(prompt, answer, steps, concept, skill, hint, tol=0, unit="", diagram="", alt=""):
    return {"k": "num", "prompt": prompt, "answer": answer, "steps": steps, "concept": concept, "skill": skill,
            "hint": hint, "tol": tol, "unit": unit, "diagram": diagram, "alt": alt}


def build(specs, seed):
    """Turn specs into MC/NUM questions with the correct option spread evenly over A-D."""
    rng = random.Random(seed)
    counts = [0, 0, 0, 0]
    for s in specs:
        if s["k"] in ("mc", "lq", "fq") and s["pos"] is not None:
            counts[s["pos"]] += 1
    out = []
    for s in specs:
        st = [S(a, text=b) for a, b in s["steps"]]
        assert s["concept"] and len(s["concept"]) <= 80, s["concept"]
        if s["k"] == "num":
            out.append(NUM(s["prompt"], s["answer"], steps=st, tolerance=s["tol"], unit=s["unit"], concept=s["concept"],
                           skill=s["skill"], hint=s["hint"], diagram=s["diagram"], diagram_alt=s["alt"]))
            continue
        if s["k"] == "fq":
            ch = [C(o, correct=(i == s["ans"]), why=s["whys"].get(i, "")) for i, o in enumerate(s["options"])]
        elif s["k"] == "lq":
            ch = [C(L, correct=(L == s["ans"]), why=s["whys"].get(L, "")) for L in "ABCD"]
        else:
            if s["pos"] is None:
                m = min(counts)
                s["pos"] = rng.choice([i for i in range(4) if counts[i] == m])
                counts[s["pos"]] += 1
            ch = [C(t, why=w) for t, w in s["wrongs"]]
            ch.insert(s["pos"], C(s["correct"], correct=True))
        out.append(MC(s["prompt"], ch, steps=st, concept=s["concept"], skill=s["skill"], hint=s["hint"],
                      diagram=s["diagram"], diagram_alt=s["alt"]))
    return out


